<?php
declare(strict_types=1);
require '../includes/security.php';
require_authentication();
require '../database/db.php';
$user_id=(int)$_SESSION['user_id'];
$csrf=htmlspecialchars(csrf_token(),ENT_QUOTES,'UTF-8');
$statement=$con->prepare('SELECT draft_id,title,created_at,image,description,category FROM draft_posts WHERE user_id=? ORDER BY created_at DESC');
$statement->bind_param('i',$user_id);$statement->execute();$result=$statement->get_result();
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><meta name="description" content="Continue writing your unfinished Weblogr stories."><meta name="theme-color" content="#0f172a"><title>Drafts | Weblogr</title><link rel="icon" type="image/svg+xml" href="../assets/weblogr-mark.svg"><link rel="stylesheet" href="style.css"><link rel="stylesheet" href="../assets/weblogr-product.css"><link rel="stylesheet" href="../assets/responsive.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><?php include 'sidebar.php';?><main class="content"><div class="all-posts-container"><header class="feed-header"><p class="eyebrow">YOUR WORKSPACE</p><h1>Drafts</h1><p>Pick up where you left off and turn unfinished ideas into published stories.</p></header><div class="page-header"><div><p class="section-title">Unpublished stories</p><p><?php echo (int)$result->num_rows;?> <?php echo $result->num_rows===1?'draft':'drafts'; ?> saved.</p></div><a href="new_post.php" class="submit"><i class="fas fa-plus"></i> New draft</a></div><?php if($result->num_rows>0):?><div class="posts-list"><?php while($row=$result->fetch_assoc()):?><article class="post-container"><div class="date-container"><span><i class="far fa-clock"></i> Saved <?php echo htmlspecialchars(date('d M Y',strtotime((string)$row['created_at'])),ENT_QUOTES,'UTF-8');?></span><?php if(!empty($row['category'])):?><span class="badge"><?php echo htmlspecialchars(ucfirst((string)$row['category']),ENT_QUOTES,'UTF-8');?></span><?php endif;?></div><h2 id="display-title"><?php echo htmlspecialchars((string)$row['title'] ?: 'Untitled story',ENT_QUOTES,'UTF-8');?></h2><?php if(!empty($row['image'])):?><img id="display-image" src="../images/<?php echo rawurlencode((string)$row['image']);?>" alt="Draft cover" loading="lazy"><?php endif;?><p id="display-para"><?php echo nl2br(htmlspecialchars((string)$row['description'],ENT_QUOTES,'UTF-8'));?></p><div class="post-actions"><a href="edit_draft.php?draft_id=<?php echo(int)$row['draft_id'];?>" class="submit"><i class="fas fa-pen"></i> Continue writing</a><form action="delete_post.php" method="post" class="inline-delete-form" data-confirm="Delete this draft? This action cannot be undone."><input type="hidden" name="draft_id" value="<?php echo(int)$row['draft_id'];?>"><input type="hidden" name="csrf_token" value="<?php echo $csrf;?>"><button type="submit" class="danger-button"><i class="fas fa-trash-alt"></i> Delete</button></form></div></article><?php endwhile;?></div><?php else:?><div class="empty-state"><div class="empty-icon"><i class="far fa-file-alt"></i></div><h2>No drafts yet</h2><p>Start a story and save it as a draft whenever you need a break. We'll keep it here until you're ready.</p><a href="new_post.php" class="submit"><i class="fas fa-pen-nib"></i> Start writing</a></div><?php endif;?></div></main><script src="../assets/interaction.js" defer></script><?php $statement->close();$con->close();?></body></html>
